package com.termux.app.workspace;
import org.junit.*;
import static org.junit.Assert.*;
public class LocalAiBenchmarkGateTest {
 @Test public void earlyStopPreventsStart(){LocalAiBenchmarkGate g=new LocalAiBenchmarkGate();int[] calls={0};g.cancel("a",()->calls[0]++);assertFalse(g.begin("a",()->calls[0]++));assertEquals(0,calls[0]);}
 @Test public void activeStopAndCleanupCannotLeaveChatCancelled(){LocalAiBenchmarkGate g=new LocalAiBenchmarkGate();boolean[] cancel={true};assertTrue(g.begin("a",()->cancel[0]=false));assertFalse(cancel[0]);g.cancel("a",()->cancel[0]=true);assertTrue(cancel[0]);g.end("a",()->cancel[0]=false);g.cancel("a",()->cancel[0]=true);assertFalse(cancel[0]);assertTrue(g.begin("b",()->cancel[0]=false));g.cancel("a",()->cancel[0]=true);assertFalse(cancel[0]);g.end("b",()->cancel[0]=false);}
 @Test public void unrelatedStopCannotErasePendingCancellation(){LocalAiBenchmarkGate g=new LocalAiBenchmarkGate();g.cancel("a",()->fail());g.cancel("old",()->fail());assertFalse(g.begin("a",()->fail()));assertTrue(g.begin("next",()->{}));}
 @Test public void overlappingBeginIsRejectedWithoutResettingRunningState(){LocalAiBenchmarkGate g=new LocalAiBenchmarkGate();assertTrue(g.begin("a",()->{}));try{g.begin("b",()->fail());fail();}catch(IllegalStateException expected){}g.end("wrong",()->fail());g.cancel("a",()->{});g.end("a",()->{});}
 @Test public void concurrentStopAndFinishNeverCancelTheFollowingChat()throws Exception{for(int i=0;i<100;i++){LocalAiBenchmarkGate g=new LocalAiBenchmarkGate();java.util.concurrent.atomic.AtomicBoolean flag=new java.util.concurrent.atomic.AtomicBoolean();assertTrue(g.begin("a",()->flag.set(false)));java.util.concurrent.CountDownLatch start=new java.util.concurrent.CountDownLatch(1);Thread stop=new Thread(()->{try{start.await();g.cancel("a",()->flag.set(true));}catch(InterruptedException e){throw new AssertionError(e);}}),finish=new Thread(()->{try{start.await();g.end("a",()->flag.set(false));}catch(InterruptedException e){throw new AssertionError(e);}});stop.start();finish.start();start.countDown();stop.join();finish.join();assertFalse(flag.get());}}
}
